SELECT 100.0 * SUM(riders) FILTER (WHERE lower(payment_method) = 'omny') / NULLIF(SUM(riders), 0) AS omny_entry_percentage
FROM gold.fct_subway_ridership_hourly
WHERE hour_date BETWEEN DATE '2026-09-01' AND DATE '2026-09-20';

SELECT AVG(temperature_f) AS average_temperature_f
FROM gold.fct_weather_hourly
WHERE hour_date = DATE '2025-07-04';

SELECT COUNT(*) AS new_jersey_station_count
FROM gold.dim_bike_station
WHERE is_new_jersey = TRUE;

SELECT COUNT(*) AS rides
FROM gold.fct_bike_trip
WHERE start_date = DATE '2026-10-02';
